1	import { BLOCK_HIDDEN_CLASS, INIT_DOM_CLASSES } from "../config/dom.config.js";
2	import type {
3	  RevealObserveOptions,
4	  TextRevealInitOptions,
5	  TextRevealOptions,
6	} from "../types/component.types.js";
7	import { Animation } from "./Animation.js";
8	import { ObserveManager } from "../manager/ObserveManager.js";
