10	export class BlockReveal extends Animation {
11	  private static _observeFrameId: number | null = null;
12	  private static readonly _observeManager = new ObserveManager();
13	
14	  static reveal(
15	    target: string | Element | Element[],
16	    options: TextRevealOptions = {},
17	  ): void {
18	    const revealClass = options.revealClass ?? INIT_DOM_CLASSES.blockUp;
19	    const elements = BlockReveal.resolveElements(target).filter(
20	      (element): element is HTMLElement => element instanceof HTMLElement,
21	    );
22	    elements.forEach((element) => {
23	      element.classList.remove(BLOCK_HIDDEN_CLASS, INIT_DOM_CLASSES.boxHidden);
24	      element.classList.add(INIT_DOM_CLASSES.blockBase);
25	      if (!element.classList.contains(revealClass)) {
26	        element.classList.add(revealClass);
27	      }
28	    });
29	  }
30	
31	  static hide(
32	    target: string | Element | Element[],
33	    options: TextRevealOptions = {},
34	  ): void {
35	    const revealClass = options.revealClass ?? INIT_DOM_CLASSES.blockUp;
36	    const elements = BlockReveal.resolveElements(target).filter(
37	      (element): element is HTMLElement => element instanceof HTMLElement,
38	    );
39	    elements.forEach((element) => {
40	      element.classList.add(INIT_DOM_CLASSES.blockBase);
41	      element.classList.remove(revealClass);
42	      element.classList.add(BLOCK_HIDDEN_CLASS, INIT_DOM_CLASSES.boxHidden);
43	    });
44	  }
45	
46	  static prepare(
47	    target: string | Element | Element[],
48	    options: TextRevealOptions = {},
49	  ): Element[] {
50	    const revealClass = options.revealClass ?? INIT_DOM_CLASSES.blockUp;
51	    const elements = BlockReveal.resolveElements(target).filter(
52	      (element): element is HTMLElement => element instanceof HTMLElement,
53	    );
54	    if (elements.length === 0) return [];
55	    elements.forEach((element) => {
56	      element.classList.remove(revealClass);
57	      element.classList.add(
58	        INIT_DOM_CLASSES.blockBase,
59	        INIT_DOM_CLASSES.boxHidden,
60	      );
61	    });
62	    return elements;
63	  }
64	
65	  static observe(
66	    target: string | Element | Element[],
67	    options: RevealObserveOptions = {},
68	  ): void {
69	    if (typeof document === "undefined") return;
70	    const revealClass = options.inviewClass ?? INIT_DOM_CLASSES.blockUp;
71	    const targets = BlockReveal.resolveElements(target).filter(
72	      (element): element is HTMLElement => element instanceof HTMLElement,
73	    );
74	    if (targets.length === 0) return;
75	    const onEnter =
76	      options.onEnter ??
77	      ((element: Element) => BlockReveal.reveal(element, { revealClass }));
78	    BlockReveal._observeFrameId = window.requestAnimationFrame(() => {
79	      BlockReveal._observeFrameId = window.requestAnimationFrame(() => {
80	        BlockReveal._observeFrameId = null;
81	        BlockReveal._observeManager.observe(
82	          targets,
83	          {
84	            onEnter,
85	            onLeave: options.onLeave,
86	          },
87	          options,
88	        );
89	      });
90	    });
91	  }
92	
93	  static init(options: TextRevealInitOptions = {}): void {
94	    if (typeof document === "undefined") return;
95	    BlockReveal.dispose();
96	    const root = options.root ?? document;
97	    const selector = options.selector ?? `.${INIT_DOM_CLASSES.blockBase}`;
98	    const targets = Array.from(root.querySelectorAll<HTMLElement>(selector));
99	    if (targets.length === 0) return;
100	    const uniqueTargets = [...new Set(targets)];
101	    BlockReveal.prepare(uniqueTargets);
102	    BlockReveal.observe(uniqueTargets, {
103	      ...options,
104	      inviewClass: INIT_DOM_CLASSES.blockUp,
105	    });
106	  }
107	
108	  static dispose(): void {
109	    if (
110	      typeof document !== "undefined" &&
111	      BlockReveal._observeFrameId != null
112	    ) {
113	      window.cancelAnimationFrame(BlockReveal._observeFrameId);
114	      BlockReveal._observeFrameId = null;
115	    }
116	    BlockReveal._observeManager.dispose();
117	  }
118	}
