61	class PageGlobalUiRuntime {
62	  private _headerUi: Header | null = null;
63	  private _workModalUi: WorkModal | null = null;
64	  private readonly _dropdownUis = new Set<Dropdown>();
65	  private readonly _pinnedRevealRuntime = new PinnedRevealRuntime();
66	  private readonly _qaManager = new QaManager();
67	
68	  init(root?: ParentNode | null): void {
69	    this._initUiToggles(root);
70	    Drawer.getInstance({
71	      revealGroups: DOM_CONFIG.drawer.revealGroups,
72	    }).init();
73	    CustomCursor.init({ root });
74	    MagneticCornerTracker.init({ root });
75	    updateStaticCornerSizes(root);
76	    TextReveal.init({
77	      root,
78	      excludeSelectors: DOM_CONFIG.maskingExcludeSelectors ?? [],
79	    });
80	    BlockReveal.init({ root });
81	    ShareButton.init({ root });
82	    ContactFormValidation.init({ root });
83	    ContactWizard.init({ root });
84	    this._qaManager.init({ root });
85	    Suspense.init({ root });
86	    Category.init(undefined, root ?? document);
87	    Marquee.init({ root });
88	    if (
89	      typeof document !== "undefined" &&
90	      document.querySelector("[data-award-hover-preview]") !== null
91	    ) {
92	      ImagePreview.init();
93	    }
94	    if (
95	      typeof document !== "undefined" &&
96	      document.querySelector("[data-why-skill-list]") !== null
97	    ) {
98	      WhySkillPreview.init();
99	    }
100	    this._pinnedRevealRuntime.init(PINNED_REVEALS);
101	  }
102	
103	  syncAfterContainerChange(): void {
104	    Drawer.syncNavActiveState();
105	    updateStaticCornerSizes();
106	  }
107	
108	  dispose(): void {
109	    this._disposeUiToggles();
110	    MagneticCornerTracker.destroyAll();
111	    CustomCursor.dispose();
112	    TextReveal.dispose();
113	    BlockReveal.dispose();
114	    Marquee.dispose();
115	    ContactWizard.dispose();
116	    this._pinnedRevealRuntime.dispose();
117	    this._qaManager.dispose();
118	  }
119	
120	  private _initUiToggles(root?: ParentNode | null): void {
121	    this._headerUi?.dispose();
122	    this._headerUi = new Header();
123	    this._headerUi.init();
124	
125	    this._workModalUi?.dispose();
126	    this._workModalUi = new WorkModal({ root });
127	    this._workModalUi.init();
128	
129	    this._dropdownUis.forEach((dropdown) => dropdown.dispose());
130	    this._dropdownUis.clear();
131	    const scope = root ?? document;
132	    const roots = scope.querySelectorAll<HTMLElement>("[data-dropdown]");
133	    roots.forEach((root) => {
134	      const dropdown = new Dropdown(root, { openClass: "is-open" });
135	      dropdown.init();
136	      this._dropdownUis.add(dropdown);
137	    });
138	  }
139	
140	  private _disposeUiToggles(): void {
141	    this._headerUi?.dispose();
142	    this._headerUi = null;
143	    this._workModalUi?.dispose();
144	    this._workModalUi = null;
145	    this._dropdownUis.forEach((dropdown) => dropdown.dispose());
146	    this._dropdownUis.clear();
147	    CloseAllExpanded.offCloseAllImmediate();
148	  }
149	}
