197	  updateDrag(
198	    viewport: WorksViewportSnapshot,
199	    halfView: WorksHalfViewBounds,
200	    pointer: WorksPointerSample,
201	  ): void {
202	    if (!this._isDragging) return;
203	    const dx = pointer.x - this._dragPrevious.x;
204	    const dy = pointer.y - this._dragPrevious.y;
205	    this._targetX += (-dx * (halfView.hW * 2)) / viewport.width;
206	    this._targetY += (dy * (halfView.hH * 2)) / viewport.height;
207	    this._velocityX = ((-dx * (halfView.hW * 2)) / viewport.width) * 0.7;
208	    this._velocityY = ((dy * (halfView.hH * 2)) / viewport.height) * 0.7;
209	    this._targetX = Math.max(
210	      -this._camPadX + halfView.hW,
211	      Math.min(this._camPadX - halfView.hW, this._targetX),
212	    );
213	    this._targetY = Math.max(
214	      -this._camPadY + halfView.hH,
215	      Math.min(this._camPadY - halfView.hH, this._targetY),
216	    );
217	    this._dragPrevious = { ...pointer };
218	  }
