303	        slice.map(async (mesh) => {
304	          if (!mesh) return;
305	          const userData = mesh.userData as WorkCardUserData;
306	          const material = mesh.material as THREE.MeshBasicMaterial;
307	          const map = material.map;
308	          if (!map || !(map instanceof THREE.CanvasTexture)) return;
