627	  private bindEvents(): void {
628	    const canvas = this.canvas;
629	    if (!canvas) return;
630	
631	    const onPointerMove = (event: PointerEvent): void => {
632	      const viewport = this.viewportRuntime.read();
633	      if (this.viewMode !== "scatter") {
634	        this.hovered = null;
635	        return;
636	      }
637	      if (!this.camera) return;
638	      if (this.activePointerId !== event.pointerId) {
639	        if (this.activePointerId === null) {
640	          this.hovered = this.hitRuntime.resolve(
641	            this.camera,
642	            viewport,
643	            { x: event.clientX, y: event.clientY },
644	            this.interactiveMeshes,
645	          );
646	        }
647	        return;
648	      }
649	      if (this.cameraMotionRuntime.isDragging) {
650	        if (
651	          !this.dragInteractionStarted &&
652	          Math.hypot(event.clientX - this.mouseDownX, event.clientY - this.mouseDownY) >=
653	            WorksSceneManager._dragStartThresholdPx
654	        ) {
655	          this.dragInteractionStarted = true;
656	          this.onInteractionStart?.();
657	        }
658	        this.cameraMotionRuntime.updateDrag(
659	          viewport,
660	          this.viewportRuntime.readHalfView(this.camera),
661	          { x: event.clientX, y: event.clientY },
662	        );
663	        this.hovered = null;
664	        return;
665	      }
666	      this.hovered = this.hitRuntime.resolve(
667	        this.camera,
668	        viewport,
669	        { x: event.clientX, y: event.clientY },
670	        this.interactiveMeshes,
671	      );
672	    };
673	    const onPointerDown = (event: PointerEvent): void => {
674	      if (this.viewMode !== "scatter" || !this.camera) return;
675	      if (event.button !== 0) return;
676	      this.mouseDownX = event.clientX;
677	      this.mouseDownY = event.clientY;
678	      this.dragInteractionStarted = false;
679	      this.activePointerId = event.pointerId;
680	      this.mouseDownMesh = this.hitRuntime.resolve(
681	        this.camera,
682	        this.viewportRuntime.read(),
683	        { x: event.clientX, y: event.clientY },
684	        this.interactiveMeshes,
685	      );
686	      this.cameraMotionRuntime.beginDrag(this.camera, {
687	        x: event.clientX,
688	        y: event.clientY,
689	      });
690	      canvas.setPointerCapture(event.pointerId);
691	    };
692	    const onPointerUp = (event: PointerEvent): void => {
693	      if (this.activePointerId !== event.pointerId) return;
694	      if (
695	        this.viewMode === "scatter" &&
696	        this.mouseDownMesh &&
697	        this.isMeshInCategory(this.mouseDownMesh) &&
698	        Math.hypot(event.clientX - this.mouseDownX, event.clientY - this.mouseDownY) <
699	          WorksSceneManager._dragStartThresholdPx
700	      ) {
701	        const userData = this.mouseDownMesh.userData as WorkCardUserData;
702	        this.onSelect?.(userData.detailPath);
703	      }
704	      this._resetPointerInteraction(event.pointerId);
705	    };
706	    const onPointerCancel = (event: PointerEvent): void => {
707	      if (this.activePointerId !== event.pointerId) return;
708	      this._resetPointerInteraction(event.pointerId);
709	    };
710	    const onPointerLeave = (): void => {
711	      if (this.activePointerId !== null) return;
712	      this.hovered = null;
713	    };
714	    const onResize = (): void => {
715	      if (!this.camera || !this.renderer) return;
716	      const viewport = this.viewportRuntime.read();
717	      if (this.camera instanceof THREE.OrthographicCamera) {
718	        const halfHeight =
719	          Math.tan((this.config.camFov * Math.PI) / 360) * this.config.camZ;
720	        const halfWidth = halfHeight * (viewport.width / viewport.height);
721	        this.camera.left = -halfWidth;
722	        this.camera.right = halfWidth;
723	        this.camera.top = halfHeight;
724	        this.camera.bottom = -halfHeight;
725	        this.camera.updateProjectionMatrix();
726	      }
727	      this.renderer.setPixelRatio(viewport.dpr);
728	      this.renderer.setSize(viewport.width, viewport.height);
729	    };
730	    canvas.addEventListener("pointermove", onPointerMove);
731	    canvas.addEventListener("pointerdown", onPointerDown);
732	    canvas.addEventListener("pointerup", onPointerUp);
733	    canvas.addEventListener("pointercancel", onPointerCancel);
734	    canvas.addEventListener("pointerleave", onPointerLeave);
735	    window.addEventListener("resize", onResize);
736	    this.cleanup.push(
737	      () => canvas.removeEventListener("pointermove", onPointerMove),
738	      () => canvas.removeEventListener("pointerdown", onPointerDown),
739	      () => canvas.removeEventListener("pointerup", onPointerUp),
740	      () => canvas.removeEventListener("pointercancel", onPointerCancel),
741	      () => canvas.removeEventListener("pointerleave", onPointerLeave),
742	      () => window.removeEventListener("resize", onResize),
743	    );
744	  }
