746	  private startLoop(): void {
747	    if (this.rafId !== null) return;
748	    if (!this.camera || !this.renderer || !this.scene) return;
749	    this.clock = new THREE.Clock();
750	    this.clock.start();
751	    const animate = (): void => {
752	      if (!this.camera || !this.renderer || !this.scene || !this.clock) {
753	        this.rafId = null;
754	        return;
755	      }
756	      this.rafId = FrameScheduler.request(animate);
757	      const delta = Math.min(this.clock.getDelta(), MAX_DELTA_SECONDS);
758	      this.update(delta);
759	      this.renderer.render(this.scene, this.camera);
760	    };
761	    animate();
762	  }
763	
764	  private stopLoop(): void {
765	    if (this.rafId !== null) {
766	      FrameScheduler.cancel(this.rafId);
767	      this.rafId = null;
768	    }
769	    this.clock?.stop();
770	    this.clock = null;
771	  }
