773	  private _resetPointerInteraction(pointerId: number): void {
774	    this.mouseDownMesh = null;
775	    this.dragInteractionStarted = false;
776	    this.cameraMotionRuntime.endDrag();
777	    this.activePointerId = null;
778	    if (this.canvas?.hasPointerCapture(pointerId)) {
779	      this.canvas.releasePointerCapture(pointerId);
780	    }
781	  }
