795	  private _centerCameraOnVisiblePositions(
796	    positions: ReadonlyArray<WorksScatterPosition>,
797	  ): void {
798	    const center = this._readVisiblePositionsCenter(positions);
799	    this.cameraMotionRuntime.setTargetPosition(center.x, center.y);
800	  }
801	
802	  private _readVisiblePositionsCenter(
803	    positions: ReadonlyArray<WorksScatterPosition>,
804	  ): WorksScatterPosition {
805	    if (positions.length === 0) {
806	      return { x: 0, y: 0 };
807	    }
808	    let minX = positions[0]?.x ?? 0;
809	    let maxX = minX;
810	    let minY = positions[0]?.y ?? 0;
811	    let maxY = minY;
812	    for (let index = 1; index < positions.length; index += 1) {
813	      const position = positions[index];
814	      if (!position) continue;
815	      minX = Math.min(minX, position.x);
816	      maxX = Math.max(maxX, position.x);
817	      minY = Math.min(minY, position.y);
818	      maxY = Math.max(maxY, position.y);
819	    }
820	    return {
821	      x: (minX + maxX) * 0.5,
822	      y: (minY + maxY) * 0.5,
823	    };
824	  }
825	}
