42	class ManagedPageStrategy implements IPageStrategy {
43	  private readonly _runtime: IPageRuntime;
44	
45	  constructor(pageConfig: ManagedPageConfig) {
46	    this._runtime = new AppManagerPageRuntime(pageConfig);
47	  }
48	
49	  async init(root?: ParentNode | null): Promise<void> {
50	    await this._runtime.init(root);
51	  }
52	
53	  dispose(): void {
54	    this._runtime.dispose();
55	  }
56	}
57	
58	class AppManagerPageRuntime implements IPageRuntime {
59	  private readonly _pageConfig: ManagedPageConfig;
60	  private _appManager: AppManager | null = null;
61	
62	  constructor(pageConfig: ManagedPageConfig) {
63	    this._pageConfig = pageConfig;
64	  }
65	
66	  async init(root?: ParentNode | null): Promise<void> {
67	    if (window.gsap?.registerPlugin && window.ScrollTrigger) {
68	      window.gsap.registerPlugin(window.ScrollTrigger);
69	    }
70	    const three = this._pageConfig.three;
71	    if (!three) {
72	      recoverPageInitFailure(
73	        "ManagedPageStrategy.init",
74	        new Error(`Missing page config for ${this._pageConfig.pageId}.`),
75	      );
76	      return;
77	    }
78	    const env = EnvSetup.shouldInit({
79	      canvasId: three.canvasId,
80	      root,
81	      allowedPageTypes: new Set(Object.keys(CONFIG_DRIVEN_PAGES)),
82	    });
83	    if (!env.shouldInit) {
84	      recoverPageInitFailure(
85	        "ManagedPageStrategy.init",
86	        new Error(env.reason ?? "Three.js page init was skipped."),
87	      );
88	      return;
89	    }
90	    this._appManager?.dispose();
91	    this._appManager = new AppManager();
92	    try {
93	      await this._appManager.run(this._pageConfig, root);
94	    } catch (error) {
95	      this._appManager?.dispose();
96	      this._appManager = null;
97	      recoverPageInitFailure("ManagedPageStrategy.init", error);
98	    }
99	  }
100	
101	  dispose(): void {
102	    this._appManager?.dispose();
103	    this._appManager = null;
104	  }
105	}
106	
107	class LazyRuntimePageStrategy implements IPageStrategy {
108	  private readonly _failureContext: string;
109	  private readonly _loadRuntime: (
110	    root?: ParentNode | null,
111	  ) => Promise<IPageRuntime>;
112	  private _runtime: IPageRuntime | null = null;
113	
114	  constructor(
115	    failureContext: string,
116	    loadRuntime: (
117	      root?: ParentNode | null,
118	    ) => Promise<IPageRuntime>,
119	  ) {
120	    this._failureContext = failureContext;
121	    this._loadRuntime = loadRuntime;
122	  }
123	
124	  async init(root?: ParentNode | null): Promise<void> {
125	    try {
126	      this._runtime?.dispose();
127	      this._runtime = null;
128	      const runtime = await this._loadRuntime(root);
129	      this._runtime = runtime;
130	      await runtime.init(root);
131	    } catch (error) {
132	      this._runtime?.dispose();
133	      this._runtime = null;
134	      recoverPageInitFailure(this._failureContext, error);
135	    }
136	  }
137	
138	  dispose(): void {
139	    this._runtime?.dispose();
140	    this._runtime = null;
141	  }
142	}
