180	export class PageController implements IPageController {
181	  private _strategy: IPageStrategy | null = null;
182	
183	  private _resolveStrategy(pageType: string): IPageStrategy {
184	    const createStrategy = PAGE_STRATEGIES[pageType];
185	    if (!createStrategy) return new NoopPageStrategy();
186	    return createStrategy();
