343	  private _resolveAboutHeroSloganKeywordStep(
344	    sceneKey: AboutSceneSectionKey,
345	    progress: number,
346	  ): number {
347	    if (sceneKey !== "heroSlogan") return 0;
348	    const keywordCount = Math.max(ABOUT_HERO_SLOGAN.keywordCount, 1);
349	    const clampedProgress = Helpers.clamp01(progress);
350	    const windowedProgress = this._resolveAboutHeroSloganKeywordProgress(
