359	  private _resolveAboutHeroSloganKeywordProgress(progress: number): number {
360	    const start = Helpers.clamp01(ABOUT_HERO_SLOGAN.progressWindowStart);
361	    const end = Helpers.clamp01(ABOUT_HERO_SLOGAN.progressWindowEnd);
362	    if (end <= start) return progress;
363	    if (progress <= start) return 0;
364	    if (progress >= end) return 1;
365	    return (progress - start) / (end - start);
366	  }
